mapper.insert:
INSERT INTO problems(
     cert_id,
     problem_type,
     problem_title
)
VALUES (
    #{certId},
    #{problemType},
    #{problemTitle}
);

 INSERT INTO short_answer_problems (
     problem_id,
     question,
     answer
 )
 VALUES (
     #{problemId},
     #{question},
     #{answer}
);

mapper.select:
SELECT
    problem_id,
    cert_id,
    problem_type,
    problem_title
FROM problems


        AND cert_id = #{certId}


        AND problem_id < #{problemId}


ORDER BY problem_id DESC
LIMIT #{size};
